// One BullMQ job per scheduled message. BullMQ delays in milliseconds rather
// than at an absolute time, so each explicit ISO-8601 instant is converted to
// a delay when the job is enqueued.
//
// Send your own schedule as msg.payload in this shape to use real data; the
// sample below runs when nothing is sent, and its dates are placeholders --
// replace them, or any instant already in the past becomes a delay of 0 and
// the notification is delivered immediately.
const userSchedules = Array.isArray(msg.payload)
    ? msg.payload
    : [
        {
            userId: "user_A",
            jobs: [
                { time: "2026-10-01T08:00:00Z", message: { type: "welcome", title: "Welcome!", content: "Thanks for signing up.", pointsAwarded: 100 } },
                { time: "2026-10-03T12:00:00Z", message: { type: "survey", title: "Quick Feedback", url: "https://example.com", rewardCode: "THANKYOU" } },
                { time: "2026-10-07T15:30:00Z", message: { type: "promotion", title: "Flash Sale", discountPercentage: 25 } },
                { time: "2026-10-15T09:00:00Z", message: { type: "billing", title: "Invoice Ready", invoiceId: "INV-001", amountDue: 49.99 } },
                { time: "2026-10-31T20:00:00Z", message: { type: "summary", title: "Monthly Wrap-up", activeDays: 14 } }
            ]
        },
        {
            userId: "user_B",
            jobs: [
                { time: "2026-10-02T10:00:00Z", message: { type: "security", title: "New Login Detected", device: "Chrome / Windows", location: "New York" } },
                { time: "2026-10-12T14:00:00Z", message: { type: "trial_expiry", title: "Trial Ending Soon", daysLeft: 3, upgradeUrl: "https://example.com" } },
                { time: "2026-10-25T18:00:00Z", message: { type: "reengage", title: "We Miss You", specialOffer: "Free Shipping Code: SHIPFREE" } }
            ]
        }
    ];

const now = Date.now();

// addBulk enqueues the whole series in one round trip. A per-notification
// jobId derived from the user, the type and the scheduled instant makes
// re-sending the same schedule idempotent: BullMQ ignores an add for a jobId
// it already holds, so a second inject cannot double-book a notification.
//
// The instant goes in as epoch milliseconds, and the parts are joined with
// "-", because BullMQ rejects a custom job id containing ":" -- which an
// ISO-8601 timestamp is full of.
msg.cmd = "addBulk";
msg.payload = userSchedules.flatMap((user) =>
    user.jobs.map((job) => {
        const scheduledAt = new Date(job.time).getTime();
        return {
            name: job.message.type,
            data: { userId: user.userId, scheduledFor: job.time, message: job.message },
            opts: {
                delay: Math.max(0, scheduledAt - now),
                jobId: `${user.userId}-${job.message.type}-${scheduledAt}`,
                removeOnComplete: 1000,
                removeOnFail: 5000
            }
        };
    })
);
return msg;

// A cron-scheduled repeating notification. The pattern is a 6-field cron
// expression (the leading field is seconds), and msg.repeat.tz fixes the zone
// so the hour does not drift with the host's own timezone or daylight saving.
//
// The message travels in msg.template.data: the template is what every job
// this scheduler generates is created from, so anything the worker needs must
// be in there rather than in the scheduler id.
msg.cmd = "upsertJobScheduler";
msg.schedulerId = "daily-digest";
msg.repeat = { pattern: "0 0 8 * * *", tz: "UTC" };
msg.template = {
    name: "digest",
    data: {
        userId: "user_A",
        message: {
            type: "digest",
            title: "Your daily digest",
            content: "Here is what happened while you were away."
        }
    }
};
return msg;

// Job Schedulers outlive a redeploy, so an example that creates one needs a
// way to remove it again.
msg.cmd = "removeJobScheduler";
msg.schedulerId = "daily-digest";
return msg;

// The worker is handed one message per notification, whether it came from the
// delayed series or from the cron scheduler. msg.payload is the job's data, so
// the notification itself is msg.payload.message.
const { userId, message } = msg.payload || {};
msg.topic = `${userId || "unknown"}/${(message && message.type) || "unknown"}`;
msg.payload = { userId, ...message };
return msg;
